var a=[{title:`De unde vine zgomotul`,text:`Pașii repetați, sfoara de sărit, burpee, aterizările grele, echipamentul care se rostogolește și ganterele scăpate transmit sunet prin clădire. Podelele subțiri pot face ca un impact mic să sune tare. O rutină care pare silențioasă într-o sală de la parter poate deranja oamenii de sub un apartament de la etaj.`},{title:`Înlocuiri mai silențioase`,text:`Înlocuiește jumping jacks cu pași în lateral, genuflexiunile cu săritură cu genuflexiuni controlate, alergarea pe loc cu marș pe loc și burpee cu impact mare cu variante în care faci pasul înapoi. Boxul cu umbra, mersul alert, ciclismul pe loc și urcările controlate pe treaptă pot crește respirația și ritmul cardiac fără aterizări tari repetate.`},{title:`Îmbunătățește configurația`,text:`Antrenează-te pe o podea liberă și antiderapantă. O saltea de exerciții poate atenua o parte din sunet și poate proteja podeaua, dar nu poate opri vibrația care se propagă prin structură. Pune greutățile jos deliberat și nu stivui echipamentul liber. Verifică dacă o platformă sau o bancă se clatină și face zgomot la fiecare repetare.`},{title:`Intensitate fără impact`,text:`Cât de greu pare cardio depinde de efortul tău, iar săriturile sunt doar o modalitate de a-l crește. Intervalele mai lungi, odihna mai scurtă care încă îți permite să te refaci sau mișcarea continuă cu impact redus dezvoltă toate condiția fizică. La antrenamentul de forță, ridicările lente și controlate și pauzele pot fi muncă grea și rămân silențioase, deci nu trebuie să te grăbești ca să faci o sesiune să pară mai grea.`},{title:`Folosirea TrainUp`,text:`În Profil, dacă săriturile sunt în regulă și cât zgomot este acceptabil sunt două setări separate. Dacă le limitezi pe amândouă, planul omite săriturile, sfoara de sărit și alte exerciții cu impact puternic și tot antrenează spre obiectivul tău cu altele mai silențioase. O saltea singură nu face un exercițiu cu sărituri silențios.`}];var t=[{label:`CDC: recomandări de activitate fizică pentru adulți`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`CDC: măsurarea intensității activității și testul vorbirii`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`Biblioteca de exerciții ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var r={sections:a,sources:t};export{r as default,a as sections,t as sources};